  row_version                  integer NOT NULL DEFAULT 1,
  code                         varchar(64) NOT NULL,
  name                         varchar(160) NOT NULL,
  purpose                      varchar(40) NOT NULL CHECK (purpose IN ('PRICING', 'ELIGIBILITY', 'FEE', 'LIMIT', 'ROUTING', 'RISK', 'CUSTOM')),
  description                  text,
  current_version_id           uuid,
  status                       varchar(40) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PENDING_APPROVAL', 'PUBLISHED', 'RETIRED')),
  owner_user_id                uuid,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_decision_table_code UNIQUE (tenant_id, code)
);
