BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA pricing TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA pricing TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA pricing GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
